op_ai_agent(parameters: {projectId, objective, workflow, runId, maxSteps, operationTimeout, allowInstall, language, provider, model}) -> jobId
{
  "id": "ai_agent",
  "inputSchema": {
    "type": "object",
    "properties": {
      "projectId": {
        "type": "string",
        "description": "Project id returned by open_file or list_projects."
      },
      "objective": {
        "type": "string",
        "description": "Concrete requested task and representative scenarios."
      },
      "workflow": {
        "type": "string",
        "description": "Task effects and completion proof.",
        "enum": [
          "investigate",
          "reconstruct",
          "patch",
          "port"
        ],
        "default": "reconstruct"
      },
      "runId": {
        "type": "string",
        "description": "Resume an existing checkpoint with the same objective/workflow.",
        "default": ""
      },
      "maxSteps": {
        "type": "integer",
        "description": "Maximum tool decisions per invocation.",
        "default": 60,
        "minimum": 1,
        "maximum": 200
      },
      "operationTimeout": {
        "type": "integer",
        "description": "Maximum child operation duration in seconds.",
        "default": 900,
        "minimum": 30,
        "maximum": 86400
      },
      "allowInstall": {
        "type": "boolean",
        "description": "Install missing official engine components for this task.",
        "default": true
      },
      "language": {
        "type": "string",
        "description": "Answer language for the AI.",
        "enum": [
          "en",
          "fr",
          "de",
          "es",
          "it",
          "pt",
          "ru",
          "zh",
          "ja",
          "ko"
        ],
        "default": "en"
      },
      "provider": {
        "type": "string",
        "description": "Override the configured AI provider for this call.",
        "enum": [
          "",
          "claude-code",
          "codex",
          "antigravity",
          "opencode",
          "anthropic",
          "openai",
          "openrouter",
          "openai-compatible",
          "ollama"
        ],
        "default": ""
      },
      "model": {
        "type": "string",
        "description": "Override the model id for this call (empty = configured/default).",
        "default": ""
      }
    },
    "required": [
      "projectId",
      "objective"
    ],
    "additionalProperties": false
  },
  "outputSchema": {
    "type": "object",
    "properties": {
      "runId": {
        "type": "string",
        "description": "Checkpoint id."
      },
      "status": {
        "type": "string",
        "description": "completed, blocked, budget-exhausted, cancelled or failed."
      },
      "answer": {
        "type": "string",
        "description": "Result with evidence and remaining limits."
      },
      "verification": {
        "type": "object",
        "description": "Server-checked completion proof."
      },
      "steps": {
        "type": "array",
        "description": "Tool decisions and actual results."
      },
      "childJobs": {
        "type": "array",
        "description": "Authenticated owning child jobs."
      }
    },
    "additionalProperties": true
  },
  "resourceRequirements": {
    "ramBytes": 67108864,
    "networkRequired": true
  },
  "permissions": [
    "network",
    "processSpawn",
    "filesystemExternal"
  ],
  "exclusiveGroups": [
    "ai-agent"
  ],
  "canRunAsync": true,
  "canCancel": true,
  "supportsProgress": true
}

