{
  "id": "analyze",
  "inputSchema": {
    "type": "object",
    "properties": {
      "projectId": {
        "type": "string",
        "description": "Project id returned by open_file or list_projects."
      },
      "engine": {
        "type": "string",
        "description": "Engine id. Empty selects the analysed (or best available) engine for the file.",
        "enum": [
          "",
          "ghidra",
          "cdec",
          "native",
          "ilspy",
          "vineflower",
          "jadx",
          "python",
          "shader",
          "javascript"
        ],
        "default": ""
